comments.suggestion_code:
SHAS=$(git rev-list "$COMMIT_RANGE" 2>/dev/null) || {
  # If rev-list fails (bad range), abort rather than feeding range syntax
  # back through as a single SHA (which git would misinterpret).
  return 0
}

comments.existing_code:
SHAS=$(git rev-list "$COMMIT_RANGE" 2>/dev/null) || {
  # If rev-list fails (bad range), try treating it as a single sha.
  SHAS="$COMMIT_RANGE"
}
